// Verify the HMAC the Next.js app sent, then flatten the payload for Airtable.
const crypto = require('crypto');

const input = $json;
const raw = typeof input.body === 'string' ? input.body : JSON.stringify(input.body ?? input);
const headers = input.headers ?? {};
const provided = String(headers['x-lexhive-signature'] ?? '').replace(/^sha256=/, '');
const secret = process.env.N8N_WEBHOOK_SECRET ?? '';

const expected = secret ? crypto.createHmac('sha256', secret).update(raw, 'utf8').digest('hex') : '';
const signaturesMatch =
  expected.length > 0 &&
  provided.length === expected.length &&
  crypto.timingSafeEqual(Buffer.from(provided, 'utf8'), Buffer.from(expected, 'utf8'));

let payload;
try {
  payload = typeof input.body === 'string' ? JSON.parse(input.body) : input.body ?? input;
} catch (error) {
  payload = null;
}

const problems = [];
if (!payload) problems.push('invalid_json');
if (payload && !payload.lead_id) problems.push('missing_lead_id');
if (payload && !payload.contact?.email) problems.push('missing_email');
if (payload && !payload.contact?.phone) problems.push('missing_phone');
if (!signaturesMatch) problems.push('invalid_signature');

const qualification = payload?.qualification ?? {};
const demographics = payload?.demographics ?? {};
const attribution = payload?.attribution ?? {};
const leadId = payload?.lead_id ?? '';

const bool = value => (value === true ? 'Yes' : value === false ? 'No' : '');

return [{
  json: {
    signatureValid: signaturesMatch,
    valid: problems.length === 0,
    problems,
    raw_body: raw,
    signature: expected ? `sha256=${expected}` : '',
    lead_id: leadId,
    submission_id: payload?.submission_id ?? '',
    session_id: payload?.session_id ?? '',
    submitted_at: payload?.submitted_at ?? '',
    payload,
    airtable: {
      'Lead ID': leadId,
      'Submission ID': payload?.submission_id ?? '',
      'First Name': payload?.contact?.first_name ?? '',
      'Last Name': payload?.contact?.last_name ?? '',
      'Email': payload?.contact?.email ?? '',
      'Phone': payload?.contact?.phone ?? '',
      'Receiving Benefits': qualification.receiving_benefits ?? '',
      'Hours Per Week': qualification.hours_per_week ?? '',
      'Years Employed': qualification.years_employed ?? '',
      'Assets': qualification.assets ?? '',
      'Expects Out Of Work': bool(qualification.expects_out_of_work),
      'Condition Start': qualification.condition_start ?? '',
      'Doctor Status': qualification.doctor_status ?? '',
      'Pending Application': bool(qualification.pending_application),
      'Attorney Status': qualification.attorney_status ?? '',
      'Attorney Firm': qualification.attorney_firm ?? '',
      'Application Denied': bool(qualification.application_denied),
      'Claim Stage': qualification.claim_stage ?? '',
      'Hearing Status': qualification.hearing_status ?? '',
      'Waiting Period': qualification.waiting_period ?? '',
      'Denial Age': qualification.denial_age ?? '',
      'Gender': demographics.gender ?? '',
      'Age Range': demographics.age_range ?? '',
      'Marital Status': demographics.marital_status ?? '',
      'UTM Source': attribution.utm?.utm_source ?? '',
      'UTM Medium': attribution.utm?.utm_medium ?? '',
      'UTM Campaign': attribution.utm?.utm_campaign ?? '',
      'Landing URL': attribution.landingUrl ?? '',
      'Submitted At': payload?.submitted_at ?? '',
      'Sync Status': 'received'
    }
  }
}];

// Build the DLQ callback the LexHive app expects. The body is signed with
// the same secret the app verifies in /api/webhooks/failures.
const crypto = require('crypto');
const original = $('Verify & Normalize').item.json;
const failure = $json;

const message =
  failure.error?.message ??
  failure.error ??
  failure.message ??
  'n8n downstream node failed';

const body = {
  source: 'n8n_webhook',
  submission_id: original.submission_id,
  lead_id: original.lead_id,
  error: String(message).slice(0, 2000),
  attempts: 1,
  payload: original.payload
};

const raw = JSON.stringify(body);
const secret = process.env.N8N_WEBHOOK_SECRET ?? '';
const signature = secret ? crypto.createHmac('sha256', secret).update(raw, 'utf8').digest('hex') : '';

return [{ json: { raw_body: raw, signature: signature ? `sha256=${signature}` : '', message: String(message) } }];
